from pathlib import Path
import os,json,subprocess,time,urllib.request,hashlib
root=Path.cwd();r=root/'.local/step07/fix-round4';stage=r/'final';proof=r/'independent-reference';(proof/'private').mkdir(parents=True,exist_ok=True)
env={**os.environ,'PATH':'<EXISTING_NODE_22_21_1_BIN>:'+os.environ['PATH'],'NODE_ENV':'production','API_PORT':'4376','WEB_PORT':'5276'};source=subprocess.check_output(['git','rev-parse','HEAD'],text=True).strip();log=(stage/'reference-runtime.log').open('w');server=subprocess.Popen(['node','--env-file=.env','apps/api/dist/main.js'],env=env,stdout=log,stderr=subprocess.STDOUT)
try:
 for n in range(60):
  try:urllib.request.urlopen('http://127.0.0.1:4376/api/health',timeout=1);break
  except Exception:time.sleep(.25)
 steps=[('reference-browser',['node',str(r.relative_to(root)/'reference-probes/browser.mjs')]),('independent-reference',['python3',str(r.relative_to(root)/'reference-probes/reference.py')]),('three-cycle-clock',['node',str(r.relative_to(root)/'reference-probes/stable-clock.mjs')]),('clock-reference',['python3',str(r.relative_to(root)/'reference-probes/clock-reference.py')])]
 for label,args in steps:
  start=time.time();file=stage/(label+'.log')
  with file.open('w')as out:p=subprocess.run(args,env=env,stdout=out,stderr=subprocess.STDOUT)
  row={'label':label,'args':args,'sourceSHA':source,'exitCode':p.returncode,'durationSeconds':round(time.time()-start,2),'log':str(file.relative_to(root)),'logSHA256':hashlib.sha256(file.read_bytes()).hexdigest(),'ownership':'Author re-execution of original independently written reference; not new IndependentReview'}
  with(stage/'commands.jsonl').open('a')as f:f.write(json.dumps(row)+'\n')
  print(json.dumps(row),flush=True)
  if p.returncode:raise SystemExit(p.returncode)
  if label=='independent-reference':
   j=json.loads((proof/'evidence/browser/evidence.json').read_text());(proof/'evidence/integrated-recovery.json').write_text(json.dumps({'browserProject':j['projectId'],'first':j['builds'][0]['build']})+'\n')
finally:
 server.terminate();server.wait(timeout=15);log.close();(stage/'reference-runtime-owner.json').write_text(json.dumps({'pid':server.pid,'owner':'step07 author own reference API','sourceSHA':source,'closedNormally':True,'API':4376})+'\n')
